1	using TutorFlow.Core.Academico;
2	using TutorFlow.Core.Autorizacion;
3	using TutorFlow.Core.Conocimiento;
4	
5	namespace TutorFlow.Core.Asistente;
6	
7	public sealed record ContextoUsuario(Usuario Usuario, DirectorioAcademico Directorio);
8	
9	public sealed record ResultadoHerramienta(string Contenido, bool IdAjeno, string? IdSolicitado = null)
10	{
11	    public static ResultadoHerramienta Texto(string contenido) => new(contenido, false);
12	
13	    public static ResultadoHerramienta Denegado(string idSolicitado) => new(string.Empty, true, idSolicitado);
14	}
15	
16	public sealed class HerramientasAsistente
17	{
18	    public const string DatosBasicos = "consultar_datos_basicos";
19	    public const string Notas = "consultar_notas";
20	    public const string Cortes = "consultar_cortes";
21	    public const string Asistencia = "consultar_asistencia";
22	    public const string Programa = "consultar_programa";
23	    public const string Estudiante = "consultar_estudiante";
24	    public const string ParametroEstudianteId = "estudianteId";
25	    public const string ParametroAsignatura = "asignatura";
26	
27	    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeEstudiante =
28	    [
29	        new(Notas, "Consulta las definitivas de cada asignatura, el promedio ponderado del periodo, la prueba académica, la habilitación y la elegibilidad de beca de la persona que pregunta, ya calculados. Úsala para preguntas sobre notas, promedio, asignaturas perdidas, habilitación o beca.", []),
30	        new(Asistencia, "Consulta las inasistencias, las faltas permitidas y las faltas restantes de cada asignatura de la persona que pregunta. Úsala para preguntas sobre asistencia o faltas.", []),
31	        new(DatosBasicos, "Consulta el nombre, el programa y el coordinador del programa de la persona que pregunta. Úsala para preguntas sobre quién es su coordinador o a qué programa pertenece.", []),
32	        new(Cortes, "Consulta las notas de los tres cortes de una asignatura de la persona que pregunta. Úsala solo cuando pregunten por la nota de un corte concreto.", [new ParametroHerramienta(ParametroAsignatura, "Nombre o código de la asignatura.", true)])
33	    ];
34	
35	    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeCoordinador =
36	    [
37	        new(Programa, "Consulta, para cada estudiante de los programas a cargo del coordinador, el promedio, la prueba académica, las asignaturas perdidas, las asignaturas sin definitiva y la asistencia sin registro. Úsala para listados y conteos del programa.", []),
38	        new(Estudiante, "Consulta el detalle de notas y asistencia de un estudiante de los programas del coordinador. Úsala cuando pregunten por un estudiante concreto.", [new ParametroHerramienta(ParametroEstudianteId, "Identificador del estudiante: las letras EST, un guion y tres dígitos.", true)])
39	    ];
40	
41	    private readonly IApiAcademica _apiAcademica;
42	    private readonly PoliticaAcceso _politicaAcceso;
43	    private readonly Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>> _manejadores;
44	
45	    public HerramientasAsistente(IApiAcademica apiAcademica, PoliticaAcceso politicaAcceso)
46	    {
47	        _apiAcademica = apiAcademica;
48	        _politicaAcceso = politicaAcceso;
49	        _manejadores = new Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>>
50	        {
51	            [DatosBasicos] = ConsultarDatosBasicos,
52	            [Notas] = ConsultarNotas,
53	            [Cortes] = ConsultarCortes,
54	            [Asistencia] = ConsultarAsistencia,
55	            [Programa] = ConsultarPrograma,
56	            [Estudiante] = ConsultarEstudiante
57	        };
58	    }
59	
60	    public static IReadOnlyList<string> NombresInternos { get; } =
61	        [.. HerramientasDeEstudiante.Concat(HerramientasDeCoordinador).Select(herramienta => herramienta.Nombre)];
62	
63	    public static IReadOnlyList<HerramientaLlm> Definir(Rol rol) =>
64	        rol == Rol.Coordinador ? HerramientasDeCoordinador : HerramientasDeEstudiante;
65	
66	    public async Task<ResultadoHerramienta> EjecutarAsync(
67	        LlamadaHerramienta llamada,
68	        ContextoUsuario contexto,
69	        RegistroConsultas registro,
70	        CancellationToken cancellationToken)
71	    {
72	        if (!EstaDisponible(llamada.Nombre, contexto.Usuario.Rol) || !_manejadores.TryGetValue(llamada.Nombre, out var manejador))
73	        {
74	            return ResultadoHerramienta.Texto(Textos.HerramientaNoDisponible);
75	        }
76	
77	        var estudianteId = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroEstudianteId);
78	        if (EsLecturaAjena(contexto, estudianteId))
79	        {
80	            return ResultadoHerramienta.Denegado(IdAuditable(estudianteId));
81	        }
82	
83	        var asignatura = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroAsignatura);
84	        return await manejador(new SolicitudHerramienta(contexto, registro, estudianteId, asignatura, cancellationToken));
85	    }
86	
87	    private static string IdAuditable(string? idSolicitado) =>
88	        idSolicitado is not null && (Identificadores.EsIdEstudiante(idSolicitado) || Identificadores.EsIdCoordinador(idSolicitado))
89	            ? idSolicitado
90	            : Textos.FormatoInvalido;
91	
92	    private static bool EstaDisponible(string nombre, Rol rol) =>
93	        Definir(rol).Any(herramienta => herramienta.Nombre == nombre);
94	
95	    private bool EsLecturaAjena(ContextoUsuario contexto, string? estudianteId) =>
96	        estudianteId is not null
97	        && !_politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, estudianteId, contexto.Directorio).Permitido;
98	
99	    private Task<ResultadoHerramienta> ConsultarDatosBasicos(SolicitudHerramienta solicitud)
100	    {
101	        var estudiante = solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == solicitud.Contexto.Usuario.Id);
102	        var contenido = FormateadorDatos.DatosBasicos(estudiante, solicitud.Contexto.Directorio);
103	        solicitud.Registro.RegistrarDatos([DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, RecursoConsultado.DatosBasicos)]);
104	        return Task.FromResult(Responder(solicitud, contenido, estudiante.Id, [RecursoConsultado.DatosBasicos], Textos.SeccionDatosBasicos));
105	    }
106	
107	    private async Task<ResultadoHerramienta> ConsultarNotas(SolicitudHerramienta solicitud)
108	    {
109	        var id = solicitud.Contexto.Usuario.Id;
110	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
111	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
112	        solicitud.Registro.RegistrarResumen(resumen);
113	        return Responder(solicitud, ConReglas(solicitud, FormateadorDatos.Notas(resumen), ReglasAplicadas.DeNotas([resumen])), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionNotas);
114	    }
115	
116	    private async Task<ResultadoHerramienta> ConsultarCortes(SolicitudHerramienta solicitud)
117	    {
118	        if (string.IsNullOrWhiteSpace(solicitud.Asignatura))
119	        {
120	            return ResultadoHerramienta.Texto(Textos.FaltaAsignatura);
121	        }
122	
123	        var id = solicitud.Contexto.Usuario.Id;
124	        var notas = await _apiAcademica.ObtenerNotasAsync(id, solicitud.CancellationToken);
125	        var contenido = FormateadorDatos.Cortes(notas, solicitud.Asignatura);
126	        var codigos = FormateadorDatos.BuscarAsignaturas(notas, solicitud.Asignatura).Select(nota => nota.Codigo);
127	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorCodigos(id, ProgramaDe(solicitud, id), codigos, RecursoConsultado.Notas));
128	        return Responder(solicitud, contenido, id, [RecursoConsultado.Notas], Textos.SeccionNotas);
129	    }
130	
131	    private async Task<ResultadoHerramienta> ConsultarAsistencia(SolicitudHerramienta solicitud)
132	    {
133	        var id = solicitud.Contexto.Usuario.Id;
134	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
135	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
136	        solicitud.Registro.RegistrarResumen(resumen);
137	        return Responder(solicitud, ConReglas(solicitud, FormateadorDatos.Asistencia(resumen), ReglasAplicadas.DeAsistencia([resumen])), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionAsistencia);
138	    }
139	
140	    private async Task<ResultadoHerramienta> ConsultarEstudiante(SolicitudHerramienta solicitud)
141	    {
142	        if (string.IsNullOrEmpty(solicitud.EstudianteId))
143	        {
144	            return ResultadoHerramienta.Texto(Textos.FaltaIdentificadorEstudiante);
145	        }
146	
147	        var directorio = solicitud.Contexto.Directorio;
148	        var estudiante = directorio.Estudiantes.First(e => e.Id == solicitud.EstudianteId);
149	        var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
150	        var detalle = string.Join("\n", FormateadorDatos.DatosBasicos(estudiante, directorio), FormateadorDatos.Notas(resumen), FormateadorDatos.Asistencia(resumen));
151	        var contenido = ConReglas(solicitud, detalle, ReglasAplicadas.DeNotasYAsistencia([resumen]));
152	        var recursos = new[] { RecursoConsultado.DatosBasicos, RecursoConsultado.Notas, RecursoConsultado.Asistencia };
153	        solicitud.Registro.Registrar(estudiante.Id, recursos, new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionAsistencia));
154	        solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.DatosBasicos));
155	        solicitud.Registro.RegistrarResumen(resumen);
156	        return Responder(solicitud, contenido, estudiante.Id, recursos, Textos.SeccionNotas);
157	    }
158	
159	    private async Task<ResultadoHerramienta> ConsultarPrograma(SolicitudHerramienta solicitud)
160	    {
161	        var programas = _politicaAcceso.ProgramasAutorizados(solicitud.Contexto.Usuario, solicitud.Contexto.Directorio);
162	        if (programas.Count == 0)
163	        {
164	            return ResultadoHerramienta.Texto(Textos.SinProgramasAsignados);
165	        }
166	
167	        var bloques = new List<string>();
168	        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
169	        {
170	            bloques.Add(await DescribirProgramaAsync(solicitud, programa));
171	        }
172	
173	        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
174	    }
175	
176	    private async Task<string> DescribirProgramaAsync(SolicitudHerramienta solicitud, Programa programa)
177	    {
178	        var estudiantes = solicitud.Contexto.Directorio.Estudiantes.Where(e => e.ProgramaId == programa.Id).ToList();
179	        var lineas = new List<string> { FormateadorDatos.EncabezadoPrograma(programa, estudiantes.Count) };
180	        var resumenes = new List<ResumenEstudiante>();
181	        foreach (var estudiante in estudiantes)
182	        {
183	            var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
184	            resumenes.Add(resumen);
185	            lineas.Add(FormateadorDatos.LineaDePrograma(estudiante, resumen));
186	            solicitud.Registro.Registrar(estudiante.Id, [RecursoConsultado.Programa, RecursoConsultado.Notas, RecursoConsultado.Asistencia], null);
187	            solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.Programa));
188	            solicitud.Registro.RegistrarResumen(resumen);
189	        }
190	
191	        solicitud.Registro.RegistrarCita(new Cita(Textos.DocumentoDatosPrograma, programa.Id));
192	        var contenido = ConReglas(solicitud, string.Join("\n", lineas), ReglasAplicadas.DePrograma(resumenes));
193	        return FormateadorDatos.Delimitar($"{Textos.DocumentoDatosPrograma} · {programa.Id}", contenido);
194	    }
195	
196	    private static string ProgramaDe(SolicitudHerramienta solicitud, string estudianteId) =>
197	        solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == estudianteId).ProgramaId;
198	
199	    private static IEnumerable<DatoConsultado> DatosDeEstudiante(Estudiante estudiante, ResumenEstudiante resumen, RecursoConsultado recursoSinAsignatura) =>
200	        DatosLeidos.PorAsignatura(resumen, estudiante.ProgramaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia)
201	            .Prepend(DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, recursoSinAsignatura));
202	
203	    private static string ConReglas(SolicitudHerramienta solicitud, string contenido, IReadOnlyList<int> entradas)
204	    {
205	        solicitud.Registro.RegistrarReglas(entradas);
206	        var reglas = ReglasAplicadas.Citas(entradas);
207	        return reglas.Count == 0 ? contenido : $"{contenido}\n{FormateadorResumen.LineaDeReglas(reglas)}";
208	    }
209	
210	    private static ResultadoHerramienta Responder(
211	        SolicitudHerramienta solicitud,
212	        string contenido,
213	        string estudianteId,
214	        IEnumerable<RecursoConsultado> recursos,
215	        string seccion)
216	    {
217	        var cita = new Cita(Textos.DocumentoDatosEstudiante, seccion);
218	        solicitud.Registro.Registrar(estudianteId, recursos, cita);
219	        return ResultadoHerramienta.Texto(FormateadorDatos.Delimitar($"{cita.Documento} · {cita.Seccion}", contenido));
220	    }
221	
222	    private Task<ResumenEstudiante> ResumirAsync(string estudianteId, CancellationToken cancellationToken) =>
223	        ResumenesAcademicos.ResumirAsync(_apiAcademica, estudianteId, cancellationToken);
224	
225	    private sealed record SolicitudHerramienta(
226	        ContextoUsuario Contexto,
227	        RegistroConsultas Registro,
228	        string? EstudianteId,
229	        string? Asignatura,
230	        CancellationToken CancellationToken);
231	}
